119	     *  a steward's approval instead; but settling a claim that needs a proof and has none is refused
120	     *  before the clerk limit is considered. */
121	    @Transactional
122	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
123	        Claim claim = lock(sheetId, claimId);
124	        refuseClosed(sheetId, claim.getDate());
125	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
126	            return voidSettled(sheetId, user, claim);
127	        }
128	        if (!claim.getStatus().canBecome(to) || to == ClaimStatus.PENDING) {
129	            throw new ResponseStatusException(HttpStatus.CONFLICT,
130	                    "A " + claim.getStatus() + " claim cannot become " + to);
131	        }
132	        String action = switch (to) {
133	            case OPEN -> "open";
134	            case SETTLED -> "settle";
135	            default -> "void";
136	        };
137	        if (!roles.may(sheetId, user, action)) {
138	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim");
139	        }
140	        if (to == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
141	            throw new ResponseStatusException(HttpStatus.CONFLICT,
142	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
143	        }
144	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
145	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
146	                    "The user who opened a claim cannot settle it");
147	        }
148	        if (to == ClaimStatus.SETTLED) {
149	            refuseUnproved(sheetId, claim);
150	        }
151	        ClaimStatus becomes = to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, claim)
152	                ? ClaimStatus.PENDING : to;
153	        return rollup.tracking(sheetId, user, () -> {
154	            Person person = person(sheetId, claim.getPersonId());
155	            if (becomes == ClaimStatus.SETTLED) {
156	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
157	                // statement bound it to, if any, and its late charge); later changes to rates, the
158	                // late percent and the sheet's today do not alter it.
159	                claim.setSettledDue(dues.figure(sheetId, person, claim));
160	            }
161	            // A void claim keeps the number it had (never reused).
162	            claim.setStatus(becomes);
163	            if (becomes == ClaimStatus.OPEN) {
164	                claim.setNumber(nextNumber(sheetId, claim.getDate()));
165	                claim.setOpenedBy(user);
166	            }
167	            logStatus(sheetId, user, person, claim);
168	            Claim saved = claims.saveAndFlush(claim);
169	            String event = switch (becomes) {
170	                case OPEN -> "CLAIM_OPENED";
171	                case PENDING -> "CLAIM_PENDING";
172	                case SETTLED -> "CLAIM_SETTLED";
173	                case VOID -> "CLAIM_VOIDED";
174	                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
175	            };
176	            String line = record(event, sheetId, user, person, saved);
177	            if (becomes == ClaimStatus.SETTLED) {
178	                line += " due=" + dueText(saved.getSettledDue());
179	            }
180	            audit.recordOnCommit(line);
181	            if (becomes == ClaimStatus.SETTLED) {
182	                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
183	            }
184	            return saved;
185	        });
186	    }
