190	     *  number and settled due, which leaves every total; the record ends with the figure reversed. */
191	    private Claim voidSettled(String sheetId, String user, Claim claim) {
192	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
193	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim");
