198	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
199	            throw new ResponseStatusException(HttpStatus.CONFLICT,
200	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement");
201	        }
202	        return rollup.tracking(sheetId, user, () -> {
