358	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
359	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
360	     *  the same date and note, the next number, opened by the user and due by the terms in force on
361	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
362	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
363	     *  allow the user's role to open a claim. */
364	    @Transactional
365	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
366	        Claim claim = lock(sheetId, claimId);
367	        refuseClosed(sheetId, claim.getDate());
368	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
369	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
370	        }
371	        if (!roles.may(sheetId, user, "open")) {
372	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
373	        }
374	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
375	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
376	                    "The amount split off must be above 0.00 and below the claim's amount");
377	        }
378	        return rollup.tracking(sheetId, user, () -> {
379	            Person person = person(sheetId, claim.getPersonId());
380	            LocalDate on = claim.getDate();
381	            Claim draft = claim.splitOff(part, nextNumber(sheetId, on), user,
382	                    dueBy(sheetId, person, on));
