386	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
387	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
388	            return new Split(original, split);
389	        });
