458	     *  no due (n/a) is within any limit, and a steward settles anything. */
459	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
460	        BigDecimal limit = sheets.clerkLimit(sheetId);
461	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
462	            return false;
463	        }
464	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
465	        return due != null && due.compareTo(limit) > 0;
466	    }
467	
468	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof
469	     *  threshold in force on the claim's date; a claim with no due (n/a) and a sheet with no threshold
470	     *  need none. */
471	    private void refuseUnproved(String sheetId, Claim claim) {
472	        BigDecimal threshold = sheets.proofThreshold(sheetId, claim.getDate());
473	        if (threshold == null || claim.getProofs() > 0) {
474	            return;
475	        }
476	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
477	        if (due != null && due.compareTo(threshold) > 0) {
478	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
479	                    "A claim whose due is above the proof threshold needs a proof first");
480	        }
481	    }
482	
483	    /** Refuse a claim of the person dated after the day they are retired from. */
484	    private static void refuseRetired(Person person, LocalDate day) {
485	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
486	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
487	                    "A claim cannot be dated after the person's retirement");
488	        }
489	    }
490	
491	    /** The day a claim of the person dated on the day is due by: its date plus the first of the
492	     *  person's own terms, their grade's and the sheet's, each as in force on the day. */
493	    private LocalDate dueBy(String sheetId, Person person, LocalDate on) {
494	        Integer own = person.getTerms();
495	        return on.plusDays(own != null ? own : sheets.termsFor(sheetId, person.gradeOn(on), on));
496	    }
497	
498	    private Person person(String sheetId, long personId) {
499	        return people.findByIdAndSheetId(personId, sheetId)
500	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
501	    }
502	
503	    /** An audit record about a claim; one that has a number carries it at the end. */
504	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
505	        String number = claim.getNumber();
506	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
507	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
508	                + (number != null ? " number=" + number : "");
